<section class="page-header"><div><span class="eyebrow">Role</span><h1><?=e((string)($role['name']??'Role'))?> permissions</h1><p>Select permissions individually or in bulk. Changes are saved as one atomic role update.</p></div><a class="btn btn-secondary" href="<?=e(url('roles.php'))?>">Back</a></section>
