<form method="post" class="content-card" data-loading-form><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>">
<div class="card-header"><div><h2>Permissions</h2><p>Permissions are identified by their API codes.</p></div><div class="toolbar-actions"><button type="button" class="btn btn-secondary" data-permission-all>Select all</button><button type="button" class="btn btn-secondary" data-permission-none>Clear all</button><button type="button" class="btn btn-secondary" data-permission-toggle>Invert</button></div></div>
<div class="permission-grid"><?php foreach($permissions as $p):$code=(string)($p['code']??'');$checked=in_array($code,$selected,true);?><label class="permission-item"><input type="checkbox" name="permissions[]" value="<?=e($code)?>" <?=$checked?'checked':''?>><span><strong><?=e((string)($p['label']??$code))?></strong><small><?=e($code)?></small></span></label><?php endforeach;?></div>
