<script>(()=>{const form=document.currentScript.previousElementSibling;const boxes=()=>[...form.querySelectorAll('input[name="permissions[]"]')];form.querySelector('[data-permission-all]').onclick=()=>boxes().forEach(x=>x.checked=true);form.querySelector('[data-permission-none]').onclick=()=>boxes().forEach(x=>x.checked=false);form.querySelector('[data-permission-toggle]').onclick=()=>boxes().forEach(x=>x.checked=!x.checked);})();</script>